"""results/summary.md + plots from results/{validation_per_shape,tuning_time}.csv and results/e2e.json."""
import json, pandas as pd, numpy as np, matplotlib; matplotlib.use('Agg'); import matplotlib.pyplot as plt, os
os.makedirs('plots', exist_ok=True)
t = pd.read_csv('results/validation_per_shape.csv'); tt = pd.read_csv('results/tuning_time.csv'); e = json.load(open('results/e2e.json'))
fig, ax = plt.subplots(1, 2, figsize=(11, 3.6), sharey=True)
for a, (dt, g) in zip(ax, t.groupby('dtype')):
    g = g.sort_values(['gemm', 'M']); x = np.arange(len(g))
    a.bar(x, g.r_ind, color=['#c0392b' if r > 1.15 else '#2c7fb8' for r in g.r_ind]); a.axhline(1.0, c='k', lw=.8); a.axhline(1.15, c='r', ls='--', lw=.8)
    a.set_xticks(x); a.set_xticklabels([f'{r.gemm}\n{r.M}' for r in g.itertuples()], fontsize=5); a.set_title(f'{dt}: ours top-1 / Inductor max-autotune (sustained)'); a.set_ylim(0.6, 1.9)
plt.tight_layout(); plt.savefig('plots/r5_ratio_per_shape.png', dpi=140); plt.close()
fig, a = plt.subplots(figsize=(5, 3.2)); m = tt.groupby(['dtype', 'method'])[['select_s', 'compile_s', 'bench_s']].median().unstack(0)
lab = []; bot = None
for i, (dt, me) in enumerate([(d, m_) for d in ('bf16', 'fp8') for m_ in ('ours1', 'ours5', 'ind_auto')]):
    r = tt[(tt.dtype == dt) & (tt.method == me)][['select_s', 'compile_s', 'bench_s']].median(); b = 0
    for c, col in zip(r, ('#999', '#2c7fb8', '#e08214')): a.bar(i, c, bottom=b, color=col); b += c
    lab.append(f'{dt}\n{me}')
a.set_xticks(range(6)); a.set_xticklabels(lab, fontsize=6); a.set_ylabel('first-call seconds (select | compile | benchmark)'); plt.tight_layout(); plt.savefig('plots/r5_tuning_time.png', dpi=140)
L = ['# Round 5 summary (generated by eval/make_summary.py)', '', '## Validation, Llama 3 8B GEMMs (median of 3 interleaved sustained reps)', '']
s = json.load(open('results/validation_summary.json'))
L += ['| dtype | geomean ours1/ind_auto | worst shape | ours5/ind_auto | ours1/cuBLAS | M<=32 worst vs oracle |', '|---|---|---|---|---|---|']
for dt, v in s.items(): L.append(f"| {dt} | {v['geomean_ours1_vs_ind_auto']:.3f} | {v['max_ratio']:.3f} {v['worst_shape']} | {v['geomean_ours5_vs_ind_auto']:.3f} | {v['geomean_ours1_vs_cublas']:.3f} | {v['small_M_max_vs_oracle']:.3f} |")
L += ['', '## First-call cost per GEMM (fresh process and caches), median seconds', '', '```\n' + tt.groupby(['dtype', 'method'])[['select_s', 'compile_s', 'bench_s', 'first_call_s']].median().round(2).to_string() + '\n```', '', '## Decoder layer (bf16, ms per layer, one rep)', '',
      '| case | stock max-autotune | ours top-1 | default |', '|---|---|---|---|']
for k in e['ind_auto']['cases']: L.append(f"| {k} | {e['ind_auto']['cases'][k]['ms']:.3f} | {e['ours1']['cases'][k]['ms']:.3f} | {e['default']['cases'][k]['ms']:.3f} |")
L += ['', '| method | total first-call s (5 shapes) | benchmark s | compile s |', '|---|---|---|---|'] + [f"| {m} | {r['total_tuning_s']:.1f} | {r['bench_s_total']:.1f} | {r['compile_s_total']:.1f} |" for m, r in e.items()]
open('results/summary.md', 'w').write('\n'.join(L) + '\n'); print('ok')
